def can_jump(nums):
    max_reach = 0
    for i, n in enumerate(nums):
        if i > max_reach: return False
        max_reach = max(max_reach, i + n)
    return True

def verify_preorder(preorder):
    stack, lo = [], float('-inf')
    for val in preorder:
        if val < lo: return False
        while stack and stack[-1] < val:
            lo = stack.pop()
        stack.append(val)
    return True

class LeakyBucket:
    def __init__(self, capacity, leak_rate):
        self.capacity = capacity
        self.leak_rate = leak_rate
        self.level = 0.0
        self.last_time = 0.0
    def _leak(self, timestamp):
        elapsed = timestamp - self.last_time
        self.level = max(0.0, self.level - elapsed * self.leak_rate)
        self.last_time = timestamp
    def add(self, tokens, timestamp):
        self._leak(timestamp)
        if self.level + tokens > self.capacity:
            return False
        self.level += tokens
        return True
    def get_level(self, timestamp):
        self._leak(timestamp)
        return self.level

from collections import Counter
import heapq
def top_k_frequent(nums, k):
    count = Counter(nums)
    return heapq.nlargest(k, count.keys(), key=count.get)

def trap(height):
    lo, hi = 0, len(height) - 1
    left_max = right_max = water = 0
    while lo < hi:
        if height[lo] < height[hi]:
            if height[lo] >= left_max: left_max = height[lo]
            else: water += left_max - height[lo]
            lo += 1
        else:
            if height[hi] >= right_max: right_max = height[hi]
            else: water += right_max - height[hi]
            hi -= 1
    return water
